        state.serialize_entry("highGuestMemSupported", &self.high_guest_mem_supported)?;
        state.serialize_entry("maintenanceModeSupported", &self.maintenance_mode_supported)?;
        state.serialize_entry("suspendedRelocateSupported", &self.suspended_relocate_supported)?;
        state.serialize_entry("restrictedSnapshotRelocateSupported", &self.restricted_snapshot_relocate_supported)?;
        state.serialize_entry("perVmSwapFiles", &self.per_vm_swap_files)?;
        state.serialize_entry("localSwapDatastoreSupported", &self.local_swap_datastore_supported)?;
